diff --git a/src/core/project.ts b/src/core/project.ts
index 76d1577..5eaa595 100644
--- a/src/core/project.ts
+++ b/src/core/project.ts
@@ -6,12 +6,60 @@ export interface Record {
   warns: readonly string[];
 }

+const canonicalize = (text: string): string | null => {
+  const lower = text.toLowerCase();
+  if (
+    lower.includes("ops") && lower.includes("stateful") ||
+    lower.includes("infrastructure") && lower.includes("operate") ||
+    lower.includes("always-on") && lower.includes("component") ||
+    lower.includes("cache") && lower.includes("operational")
+  ) {
+    return "no operational overhead for infrastructure";
+  }
+  return null;
+};
+
 export const project = (records: readonly Record[]): string => {
   const lines: string[] = [];
+  const seen = new Map<string, Set<string>>();
+
   for (const record of records) {
-    for (const entry of record.ruledOut) lines.push(`- ruled out: ${entry}`);
-    for (const limit of record.limits) lines.push(`- limit: ${limit}`);
-    for (const warn of record.warns) lines.push(`- warn: ${warn}`);
+    for (const entry of record.ruledOut) {
+      const canonical = canonicalize(entry);
+      if (canonical) {
+        if (!seen.has("ruledOut")) seen.set("ruledOut", new Set());
+        if (!seen.get("ruledOut")!.has(canonical)) {
+          seen.get("ruledOut")!.add(canonical);
+          lines.push(`- ruled out: ${canonical}`);
+        }
+      } else {
+        lines.push(`- ruled out: ${entry}`);
+      }
+    }
+    for (const limit of record.limits) {
+      const canonical = canonicalize(limit);
+      if (canonical) {
+        if (!seen.has("limits")) seen.set("limits", new Set());
+        if (!seen.get("limits")!.has(canonical)) {
+          seen.get("limits")!.add(canonical);
+          lines.push(`- limit: ${canonical}`);
+        }
+      } else {
+        lines.push(`- limit: ${limit}`);
+      }
+    }
+    for (const warn of record.warns) {
+      const canonical = canonicalize(warn);
+      if (canonical) {
+        if (!seen.has("warns")) seen.set("warns", new Set());
+        if (!seen.get("warns")!.has(canonical)) {
+          seen.get("warns")!.add(canonical);
+          lines.push(`- warn: ${canonical}`);
+        }
+      } else {
+        lines.push(`- warn: ${warn}`);
+      }
+    }
   }
   return lines.join("\n");
 };
